import { createClient } from "@supabase/supabase-js"
import { encryptFields, decryptFields } from "@/lib/crypto"
import { NextResponse } from "next/server"

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)

export async function GET() {
  try {
    const { data: config, error: configError } = await supabase
      .from("platform_settings")
      .select("*")
      .eq("key", "payments_config")
      .maybeSingle()

    // Ignorar error PGRST116 (no rows returned)
    if (configError && configError.code !== "PGRST116") {
      console.error("Error fetching config:", configError)
    }

    // Obtener estadísticas de suscripciones
    const { data: subscriptions } = await supabase.from("store_purchased_features").select("*")

    const stats = {
      total_subscribers: subscriptions?.length || 0,
      active_subscriptions: subscriptions?.filter((s: any) => s.is_active).length || 0,
      monthly_revenue_ars: 0,
      monthly_revenue_usd: 0,
      canceled_this_month: 0,
    }

    const defaultConfig = {
      stripe_enabled: false,
      stripe_publishable_key: "",
      stripe_secret_key: "",
      stripe_webhook_secret: "",
      bank_name: "Wells Fargo",
      bank_account_last4: "",
      customer_currency: "ARS",
      payout_currency: "USD",
    }

    const rawConfig = config?.value || defaultConfig
    const decryptedConfig = decryptFields(rawConfig, ["stripe_secret_key","stripe_webhook_secret","mp_access_token","paypal_client_secret","mobbex_api_key","mobbex_access_token"])

    return NextResponse.json({
      config: decryptedConfig,
      stats,
    }, { headers: { "Cache-Control": "no-store, no-cache, must-revalidate" } })
  } catch (error) {
    console.error("Error fetching payments config:", error)
    return NextResponse.json({
      config: {
        stripe_enabled: false,
        stripe_publishable_key: "",
        stripe_secret_key: "",
        stripe_webhook_secret: "",
        bank_name: "Wells Fargo",
        bank_account_last4: "",
        customer_currency: "ARS",
        payout_currency: "USD",
      },
      stats: {
        total_subscribers: 0,
        active_subscriptions: 0,
        monthly_revenue_ars: 0,
        monthly_revenue_usd: 0,
        canceled_this_month: 0,
      },
    }, { headers: { "Cache-Control": "no-store, no-cache, must-revalidate" } })
  }
}

export async function POST(request: Request) {
  try {
    const config = await request.json()

    // Cifrar campos sensibles antes de guardar
    const encryptedConfig = encryptFields(config, ["stripe_secret_key","stripe_webhook_secret","mp_access_token","paypal_client_secret","mobbex_api_key","mobbex_access_token"])

    // Guardar configuración
    const { error } = await supabase.from("platform_settings").upsert(
      {
        key: "payments_config",
        value: encryptedConfig,
        updated_at: new Date().toISOString(),
      },
      {
        onConflict: "key",
      },
    )

    if (error) throw error

    return NextResponse.json({ success: true }, { headers: { "Cache-Control": "no-store, no-cache, must-revalidate" } })
  } catch (error) {
    console.error("Error saving payments config:", error)
    return NextResponse.json({ error: "Error al guardar" }, { status: 500, headers: { "Cache-Control": "no-store" } })
  }
}
